# test_scope.py
import pytest

log = []

@pytest.fixture(scope="module")
def database():
    log.append("connect")              # expensive: once per module
    yield {"rows": []}
    log.append("disconnect")

@pytest.fixture
def transaction(database):
    log.append("begin")
    yield database
    database["rows"].clear()           # rollback after every test
    log.append("rollback")

def test_insert(transaction):
    transaction["rows"].append(1)
    assert transaction["rows"] == [1]

def test_isolated(transaction):
    assert transaction["rows"] == []
    assert log == ["connect", "begin", "rollback", "begin"]

