from unittest.mock import Mock
class PaymentError(Exception): pass

def checkout(cart_total, gateway):
    try:
        return gateway.charge(amount=cart_total, currency="EUR")["id"]
    except PaymentError:
        return None

def test_checkout_charges_total():
    gateway = Mock()
    gateway.charge.return_value = {"id": "ch_1"}
    assert checkout(42, gateway) == "ch_1"
    gateway.charge.assert_called_once_with(amount=42, currency="EUR")

def test_checkout_handles_decline():
    gateway = Mock()
    gateway.charge.side_effect = PaymentError("declined")
    assert checkout(42, gateway) is None

