# test_warn_log.py
import logging, warnings
import pytest

log = logging.getLogger("billing")

def old_total(xs):
    warnings.warn("old_total is deprecated; use total", DeprecationWarning)
    return sum(xs)

def refund(amount):
    if amount > 1000:
        log.warning("large refund: %s", amount)
    return -amount

def test_deprecation():
    with pytest.warns(DeprecationWarning, match="use total"):
        assert old_total([1, 2]) == 3

def test_large_refund_logged(caplog):
    caplog.set_level(logging.INFO, logger="billing")
    refund(5000)
    assert caplog.messages == ["large refund: 5000"]
    assert caplog.records[0].levelname == "WARNING"

