import pytest

def pytest_addoption(parser):
    parser.addoption("--runslow", action="store_true", help="run slow tests")

def pytest_configure(config):
    config.addinivalue_line("markers", "slow: mark test as slow")

def pytest_collection_modifyitems(config, items):
    if config.getoption("--runslow"):
        return
    skip_slow = pytest.mark.skip(reason="need --runslow")
    for item in items:
        if "slow" in item.keywords:
            item.add_marker(skip_slow)

@pytest.hookimpl(wrapper=True)
def pytest_runtest_makereport(item, call):
    report = yield
    if report.when == "call" and report.failed:
        print(f"\nFAILED {item.nodeid}: save artifacts here")
    return report

# conftest.py: collect *.yaml files as tests (custom collector + item)
import pytest, yaml

def pytest_collect_file(parent, file_path):
    if file_path.suffix == ".yaml" and file_path.name.startswith("test"):
        return YamlFile.from_parent(parent, path=file_path)

class YamlFile(pytest.File):
    def collect(self):
        for name, spec in yaml.safe_load(self.path.read_text()).items():
            yield YamlItem.from_parent(self, name=name, spec=spec)

class YamlItem(pytest.Item):
    def __init__(self, *, spec, **kwargs):
        super().__init__(**kwargs)
        self.spec = spec
    def runtest(self):
        if eval(self.spec["expr"]) != self.spec["equals"]:
            raise AssertionError(f"{self.spec['expr']} != {self.spec['equals']}")
    def reportinfo(self):
        return self.path, 0, f"yaml: {self.name}"

